-- STRATEGY_CLOSE transversal governance. CLOSE != SUPERSEDE. Source-first; no Strategy is closed by this migration.
DO $pre$ DECLARE c int; d text; BEGIN
 IF EXISTS(select 1 from public.lf_operation_registry where operation_code='CIERRE_ESTRATEGIA_LF') THEN raise exception 'LF_STRATEGY_CLOSE_OPERATION_EXISTS'; END IF;
 IF EXISTS(select 1 from public.lf_router_action_registry where asset_type='STRATEGY' and action_code='STRATEGY_CLOSE') THEN raise exception 'LF_STRATEGY_CLOSE_ROUTE_EXISTS'; END IF;
 SELECT count(*) INTO c FROM public.lf_activos WHERE codigo_activo IN ('POL-LF-OPERATION-LIFECYCLE','POL-LF-POLICY-CONSUMPTION','POL-LF-SOURCE-RESOLUTION','POL-LF-STATE-MODEL');
 IF c<>4 THEN raise exception 'LF_STRATEGY_CLOSE_POLICY_GAP:%',c; END IF;
 SELECT pg_get_functiondef('public.lf_router_resolve_v1(text,text,text,text,text)'::regprocedure) INTO d;
 IF strpos(d,$x$elsif v_req ~ '(^| )(policy|politica|regla)( |$)' then v_type_hint := 'REGLA';$x$)=0 OR strpos(d,$x$if v_req ~ '(^| )(consulta|consultar|estado|metadata|existe)( |$)' then v_action:='ASSET_INSPECTION';$x$)=0 THEN raise exception 'LF_STRATEGY_CLOSE_ROUTER_SOURCE_DRIFT'; END IF;
END $pre$;

