INSERT INTO public.lf_router_action_registry(asset_type,action_code,operation_code,operation_resolution,requires_existing_target,requires_missing_target,write_allowed,status,notes,created_by_execution_id)
VALUES('STRATEGY','STRATEGY_CLOSE','CIERRE_ESTRATEGIA_LF','STATIC',false,false,true,'ACTIVE','Exact Strategy snapshot resolved inside operation; Router master-asset existence is not authoritative.','EXEC-BOOTSTRAP-CIERRE-ESTRATEGIA-LF-20260914-001');

DO $patch$ DECLARE d text; n text; a text:=$x$    elsif v_req ~ '(^| )(policy|politica|regla)( |$)' then v_type_hint := 'REGLA';
    elsif v_req ~ '(^| )(doc|documento)( |$)' then v_type_hint := 'DOC';$x$; b text:=$x$    elsif v_req ~ '(^| )(policy|politica|regla)( |$)' then v_type_hint := 'REGLA';
    elsif v_req ~ '(^| )(estrategia|strategy)( |$)' then v_type_hint := 'STRATEGY';
    elsif v_req ~ '(^| )(doc|documento)( |$)' then v_type_hint := 'DOC';$x$; c text:=$x$    if v_req ~ '(^| )(consulta|consultar|estado|metadata|existe)( |$)' then v_action:='ASSET_INSPECTION';
    elsif v_type_hint='PERFIL' and v_req ~$x$; e text:=$x$    if v_req ~ '(^| )(consulta|consultar|estado|metadata|existe)( |$)' then v_action:='ASSET_INSPECTION';
    elsif v_type_hint='STRATEGY' and v_req ~ '(^| )(cierra|cerrar|cierre|finaliza|finalizar)( |$)' then v_action:='STRATEGY_CLOSE';
    elsif v_type_hint='PERFIL' and v_req ~$x$; BEGIN SELECT pg_get_functiondef('public.lf_router_resolve_v1(text,text,text,text,text)'::regprocedure) INTO d; IF strpos(d,a)=0 OR strpos(d,c)=0 THEN raise exception 'LF_STRATEGY_CLOSE_ROUTER_SOURCE_DRIFT'; END IF; n:=replace(replace(d,a,b),c,e); EXECUTE n; END $patch$;

CREATE OR REPLACE FUNCTION public.lf_strategy_snapshot_revision_sha256_v1(p_snapshot_id bigint) RETURNS text LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public,extensions AS $$ SELECT encode(extensions.digest(to_jsonb(s)::text,'sha256'),'hex') FROM public.lf_strategy_snapshots s WHERE s.id=p_snapshot_id $$;
REVOKE ALL ON FUNCTION public.lf_strategy_snapshot_revision_sha256_v1(bigint) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.lf_strategy_snapshot_revision_sha256_v1(bigint) TO service_role;

CREATE OR REPLACE FUNCTION public.lf_strategy_close_write_v1(p_execution_id text,p_snapshot_id bigint,p_expected_revision_sha256 text,p_reason text,p_disposition text,p_evidence jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,extensions AS $f$
DECLARE x public.lf_operation_execution%rowtype; s public.lf_strategy_snapshots%rowtype; a public.lf_strategy_snapshots%rowtype; bh text; ah text; cl jsonb; nowv timestamptz:=clock_timestamp(); sw int; oc int;
BEGIN
 IF btrim(coalesce(p_execution_id,''))='' OR p_snapshot_id IS NULL OR p_expected_revision_sha256 !~ '^[0-9a-f]{64}$' OR btrim(coalesce(p_reason,''))='' OR p_disposition NOT IN ('TERMINAL_COMPLETE','TERMINAL_BLOCKED') OR jsonb_typeof(p_evidence)<>'object' THEN raise exception 'LF_STRATEGY_CLOSE_INPUT_INVALID'; END IF;
 SELECT * INTO x FROM public.lf_operation_execution WHERE execution_id=p_execution_id; IF NOT FOUND OR x.operation_code<>'CIERRE_ESTRATEGIA_LF' OR x.status<>'IN_PROGRESS' OR x.target_type<>'STRATEGY' THEN raise exception 'LF_STRATEGY_CLOSE_EXECUTION_BINDING_MISMATCH'; END IF;
 SELECT * INTO s FROM public.lf_strategy_snapshots WHERE id=p_snapshot_id FOR UPDATE; IF NOT FOUND OR x.target_code<>s.snapshot_code THEN raise exception 'LF_STRATEGY_CLOSE_TARGET_MISMATCH'; END IF;
 IF coalesce(s.metadata->'strategy_close'->>'status','')='CLOSED' THEN IF s.metadata->'strategy_close'->>'execution_id'=p_execution_id THEN RETURN jsonb_build_object('result','ALREADY_CLOSED_IDEMPOTENT','snapshot_id',s.id,'close_receipt',s.metadata->'strategy_close'); END IF; raise exception 'LF_STRATEGY_CLOSE_ALREADY_CLOSED'; END IF;
 bh:=encode(extensions.digest(to_jsonb(s)::text,'sha256'),'hex'); IF bh<>p_expected_revision_sha256 THEN raise exception 'LF_STRATEGY_CLOSE_STALE_REVISION'; END IF;
 IF coalesce(p_evidence->>'safe_work_remaining_count','') !~ '^[0-9]+$' OR coalesce(p_evidence->>'open_executable_causal_chains','') !~ '^[0-9]+$' THEN raise exception 'LF_STRATEGY_CLOSE_ELIGIBILITY_COUNTS_REQUIRED'; END IF; sw:=(p_evidence->>'safe_work_remaining_count')::int; oc:=(p_evidence->>'open_executable_causal_chains')::int;
 IF sw<>0 OR oc<>0 OR coalesce((p_evidence->>'no_supersede_requested')::boolean,false) IS NOT TRUE OR jsonb_typeof(p_evidence->'backlog_disposition_map')<>'object' OR jsonb_typeof(p_evidence->'risk_disposition_map')<>'object' THEN raise exception 'LF_STRATEGY_CLOSE_NOT_ELIGIBLE'; END IF;
 IF p_evidence ? 'open_blockers' AND jsonb_typeof(p_evidence->'open_blockers')<>'array' THEN raise exception 'LF_STRATEGY_CLOSE_BLOCKERS_INVALID'; END IF;
 IF p_disposition='TERMINAL_COMPLETE' AND jsonb_array_length(coalesce(p_evidence->'open_blockers','[]'::jsonb))>0 THEN raise exception 'LF_STRATEGY_CLOSE_FALSE_COMPLETE'; END IF;
 IF p_disposition='TERMINAL_BLOCKED' AND jsonb_array_length(coalesce(p_evidence->'open_blockers','[]'::jsonb))=0 THEN raise exception 'LF_STRATEGY_CLOSE_BLOCKED_REQUIRES_BLOCKER'; END IF;
 cl:=jsonb_build_object('status','CLOSED','disposition',p_disposition,'reason_code',p_reason,'execution_id',p_execution_id,'closed_at',nowv,'safe_work_remaining_count',sw,'open_executable_causal_chains',oc,'open_blockers',coalesce(p_evidence->'open_blockers','[]'::jsonb),'backlog_disposition_map',p_evidence->'backlog_disposition_map','risk_disposition_map',p_evidence->'risk_disposition_map','baseline_revision_sha256',bh,'superseded',false);
 UPDATE public.lf_strategy_snapshots SET metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{strategy_close}',cl,true),evidence_refs=coalesce(evidence_refs,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('type','STRATEGY_CLOSE','execution_id',p_execution_id,'refs',coalesce(p_evidence->'evidence_refs','[]'::jsonb))),change_log=coalesce(change_log,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('change_type','STRATEGY_CLOSE','execution_id',p_execution_id,'closed_at',nowv,'reason_code',p_reason,'disposition',p_disposition,'superseded',false)),runtime_state='NO_HABILITADO',impact_policy='BLOQUEADO',visibility='READ_ONLY_INTERNAL',updated_at=nowv,updated_by_execution_id=p_execution_id WHERE id=s.id RETURNING * INTO a;
 ah:=encode(extensions.digest(to_jsonb(a)::text,'sha256'),'hex'); IF a.status IS DISTINCT FROM s.status OR a.archived_at IS DISTINCT FROM s.archived_at OR a.archived_reason IS DISTINCT FROM s.archived_reason OR a.runtime_state<>'NO_HABILITADO' OR a.impact_policy<>'BLOQUEADO' OR a.visibility<>'READ_ONLY_INTERNAL' THEN raise exception 'LF_STRATEGY_CLOSE_POSTWRITE_INVARIANT'; END IF;
 RETURN jsonb_build_object('result','STRATEGY_CLOSED_WITH_EVIDENCE','snapshot_id',a.id,'snapshot_code',a.snapshot_code,'close_receipt',a.metadata->'strategy_close','before_revision_sha256',bh,'after_revision_sha256',ah,'changed_paths',jsonb_build_array('metadata.strategy_close','evidence_refs.append','change_log.append','runtime_state','impact_policy','visibility','updated_at','updated_by_execution_id'));
END $f$;
REVOKE ALL ON FUNCTION public.lf_strategy_close_write_v1(text,bigint,text,text,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.lf_strategy_close_write_v1(text,bigint,text,text,text,jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_lf_strategy_closed_immutable_v1() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$ BEGIN IF coalesce(OLD.metadata->'strategy_close'->>'status','')='CLOSED' THEN raise exception 'LF_STRATEGY_CLOSED_READ_ONLY:%',OLD.snapshot_code USING errcode='23514'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.fn_lf_strategy_closed_immutable_v1() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER trg_lf_strategy_closed_immutable_v1 BEFORE UPDATE OR DELETE ON public.lf_strategy_snapshots FOR EACH ROW EXECUTE FUNCTION public.fn_lf_strategy_closed_immutable_v1();

CREATE OR REPLACE FUNCTION private.fn_lf_strategy_closed_event_stream_guard_v1() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,private AS $$ BEGIN IF NEW.entidad_tipo='STRATEGY_SNAPSHOT' AND EXISTS(select 1 from public.lf_strategy_snapshots s where s.snapshot_code=NEW.entidad_codigo and coalesce(s.metadata->'strategy_close'->>'status','')='CLOSED') THEN raise exception 'LF_STRATEGY_CLOSED_EVENT_STREAM_READ_ONLY:%',NEW.entidad_codigo USING errcode='23514'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION private.fn_lf_strategy_closed_event_stream_guard_v1() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER trg_00_lf_strategy_closed_event_stream_guard_v1 BEFORE INSERT ON public.lf_eventos FOR EACH ROW EXECUTE FUNCTION private.fn_lf_strategy_closed_event_stream_guard_v1();

CREATE OR REPLACE VIEW public.v_lf_strategy_latest WITH (security_invoker=true) AS WITH c AS (
 SELECT id,created_at,evento_tipo,entidad_codigo,snapshot_code,family,version,status,project_code,front_code,canonical_store,descripcion,severidad,origen,payload FROM public.v_lf_strategy_events WHERE snapshot_code IS NOT NULL
 UNION ALL SELECT -s.id,s.updated_at,'STRATEGY_CLOSED',s.snapshot_code,s.snapshot_code,s.snapshot_family,s.version,'CLOSED',s.project_code,s.front_code,'lf_strategy_snapshots','Governed terminal Strategy close','INFO','EXECUTION:'||coalesce(s.metadata->'strategy_close'->>'execution_id','UNKNOWN'),jsonb_build_object('snapshot_id',s.id,'snapshot_code',s.snapshot_code,'family',s.snapshot_family,'version',s.version,'status','CLOSED','project_code',s.project_code,'front_code',s.front_code,'mode','TERMINAL_READ_ONLY','canonical_store','lf_strategy_snapshots','strategy_close',s.metadata->'strategy_close') FROM public.lf_strategy_snapshots s WHERE coalesce(s.metadata->'strategy_close'->>'status','')='CLOSED')
SELECT DISTINCT ON(snapshot_code) id,created_at,evento_tipo,entidad_codigo,snapshot_code,family,version,status,project_code,front_code,canonical_store,descripcion,severidad,origen,payload FROM c ORDER BY snapshot_code,created_at DESC,id DESC;

DO $post$ DECLARE c int; r jsonb; d text; BEGIN
 SELECT count(*) INTO c FROM public.lf_operation_steps WHERE operation_code='CIERRE_ESTRATEGIA_LF' AND required AND active; IF c<>9 THEN raise exception 'LF_STRATEGY_CLOSE_STEP_COUNT:%',c; END IF;
 SELECT count(*) INTO c FROM public.lf_operation_step_contracts WHERE operation_code='CIERRE_ESTRATEGIA_LF' AND status='ACTIVE_ENFORCEMENT'; IF c<>9 THEN raise exception 'LF_STRATEGY_CLOSE_CONTRACT_COUNT:%',c; END IF;
 SELECT count(*) INTO c FROM public.lf_operation_step_judge_bindings WHERE operation_code='CIERRE_ESTRATEGIA_LF' AND status='ACTIVE_ENFORCEMENT'; IF c<>9 THEN raise exception 'LF_STRATEGY_CLOSE_BINDING_COUNT:%',c; END IF;
 SELECT count(*) INTO c FROM public.lf_operation_policy_bindings WHERE operation_code='CIERRE_ESTRATEGIA_LF' AND required AND binding_status='ACTIVE'; IF c<>4 THEN raise exception 'LF_STRATEGY_CLOSE_POLICY_COUNT:%',c; END IF;
 r:=public.lf_router_resolve_v1('cerrar estrategia gobernada',null,'STRATEGY_CLOSE','STRATEGY','ROUTER'); IF r->>'status'<>'READY_TO_EXECUTE' OR r->>'operation_code'<>'CIERRE_ESTRATEGIA_LF' THEN raise exception 'LF_STRATEGY_CLOSE_EXPLICIT_ROUTE_FAIL:%',r; END IF;
 r:=public.lf_router_resolve_v1('cerrar estrategia S26',null,null,null,'ROUTER'); IF r->>'status'<>'READY_TO_EXECUTE' OR r->>'action_code'<>'STRATEGY_CLOSE' OR r->>'operation_code'<>'CIERRE_ESTRATEGIA_LF' THEN raise exception 'LF_STRATEGY_CLOSE_NATURAL_ROUTE_FAIL:%',r; END IF;
 SELECT pg_get_viewdef('public.v_lf_strategy_latest'::regclass,true) INTO d; IF strpos(d,'STRATEGY_CLOSED')=0 OR strpos(d,'strategy_close')=0 THEN raise exception 'LF_STRATEGY_CLOSE_VIEW_FAIL'; END IF;
END $post$;

